import React, { useState } from 'react';

function DestinationGrid() {
  const [currentTicketIdx, setCurrentTicketIdx] = useState(0);
  const [fade, setFade] = useState(true);

  // 💡 [데이터 구조] 티켓 목록 데이터 (이미지 경로만 원하는 파일/URL로 교체하시면 됩니다)
  const ticketList = [
    {
      id: 1,
      title: "아비정전 4K 리마스터링",
      subtitle: "메가박스가 제안하는 <아비정전 4K 리마스터링>을 가장 잘 간직하는 방법",
      ticketNumber: "No. 43",
      // 👉 메인 티켓 이미지 경로
      mainPoster: "", 
      // 👉 뒤쪽에 살짝 겹쳐서 보이는 배경 티켓 이미지 경로
      backPoster: "" 
    },
    {
      id: 2,
      title: "싱어게인",
      subtitle: "메가박스가 제안하는 <싱어게인>을 가장 잘 간직하는 방법",
      ticketNumber: "No. 105",
      mainPoster: "",
      backPoster: ""
    },
    {
      id: 3,
      title: "인 더 그레이",
      subtitle: "메가박스가 제안하는 <인 더 그레이>를 가장 잘 간직하는 방법",
      ticketNumber: "No. 184",
      mainPoster: "",
      backPoster: ""
    }
  ];

  // 부드러운 페이드 인/아웃 전환 효과
  const changeSlide = (newIndex) => {
    setFade(false);
    setTimeout(() => {
      setCurrentTicketIdx(newIndex);
      setFade(true);
    }, 200);
  };

  const handlePrev = () => {
    const nextIdx = currentTicketIdx === 0 ? ticketList.length - 1 : currentTicketIdx - 1;
    changeSlide(nextIdx);
  };

  const handleNext = () => {
    const nextIdx = currentTicketIdx === ticketList.length - 1 ? 0 : currentTicketIdx + 1;
    changeSlide(nextIdx);
  };

  const currentTicket = ticketList[currentTicketIdx];

  return (
    <section className="w-full bg-[#fbfbfa] pt-12 pb-0 flex flex-col items-center relative overflow-hidden">
      
      {/* 1. 상단 '혜택' 및 오리지널 티켓 쇼케이스 영역 */}
      <div className="w-full max-w-6xl px-6">
        <div className="flex justify-between items-center mb-6 pb-3">
          <h2 className="text-xl font-black text-[#503396] tracking-tight">혜택</h2>
          <button className="text-xl text-zinc-600 font-bold hover:text-black">+</button>
        </div>

        <div className="flex flex-col md:flex-row items-center justify-between gap-12 py-2">
          
          {/* [좌측] 설명 텍스트 영역 (페이드 효과 적용) */}
          <div className={`max-w-md space-y-3 z-10 transition-opacity duration-300 ${fade ? 'opacity-100' : 'opacity-0'}`}>
            <span className="text-xs font-bold text-zinc-500 block">메가박스 오리지널 티켓</span>
            <h3 className="text-4xl md:text-6xl font-black text-zinc-900 tracking-tight leading-none">
              ORIGINAL<br />TICKET
            </h3>
            <p className="text-xs text-zinc-600 font-medium pt-2 leading-relaxed">
              {currentTicket.subtitle}
            </p>

            {/* 인디케이터 및 컨트롤러 */}
            <div className="flex items-center gap-4 pt-4">
              <div className="w-32 h-1 bg-zinc-200 relative rounded-full overflow-hidden">
                <div 
                  className="h-full bg-[#503396] transition-all duration-300"
                  style={{ width: `${((currentTicketIdx + 1) / ticketList.length) * 100}%` }}
                />
              </div>
              <div className="flex items-center gap-2 text-xs font-black text-zinc-700">
                <button onClick={handlePrev} className="hover:text-[#503396] px-0.5 text-zinc-500">&lt;</button>
                <button onClick={handleNext} className="hover:text-[#503396] px-0.5 text-zinc-500">&gt;</button>
                <span className="text-zinc-300 font-normal">|</span>
                <span className="font-bold text-zinc-800">{currentTicketIdx + 1} / {ticketList.length}</span>
              </div>
            </div>
          </div>

          {/* [우측] 겹쳐진 오리지널 티켓 카드 구조 */}
          <div className={`relative flex items-center justify-center mr-12 transition-opacity duration-300 ${fade ? 'opacity-100' : 'opacity-0'}`}>
            
            {/* 💡 [주석: 뒤쪽에 겹쳐지는 보조 티켓 이미지 공간] */}
            <div className="absolute -right-16 top-2 w-64 h-[370px] rounded-2xl overflow-hidden shadow-lg border border-zinc-200 bg-zinc-200 opacity-80 rotate-6 pointer-events-none flex items-center justify-center">
              {currentTicket.backPoster ? (
                <img src={currentTicket.backPoster} alt="back ticket" className="w-full h-full object-cover filter brightness-90" />
              ) : (
                <span className="text-xs font-bold text-zinc-500">배경 티켓 이미지 공간</span>
              )}
            </div>

            {/* 메인 티켓 카드 */}
            <div className="relative w-72 h-[410px] rounded-2xl overflow-hidden shadow-2xl border border-zinc-300 bg-white flex flex-col z-10">
              <div className="bg-zinc-100 px-4 py-2 border-b border-dashed border-zinc-300 flex justify-between items-center text-[10px] text-zinc-500 font-bold">
                <span className="text-zinc-600">MEGABOX ORIGINAL TICKET</span>
                <span className="text-zinc-800">{currentTicket.ticketNumber}</span>
              </div>
              
              {/* 💡 [주석: 메인 오리지널 티켓 포스터 이미지 공간] */}
              <div className="relative flex-1 overflow-hidden bg-zinc-200 flex items-center justify-center">
                {currentTicket.mainPoster ? (
                  <img src={currentTicket.mainPoster} alt={currentTicket.title} className="w-full h-full object-cover" />
                ) : (
                  <span className="text-xs font-bold text-zinc-500 text-center px-4">메인 티켓 이미지 공간<br/>(여기에 이미지를 넣어주세요)</span>
                )}
              </div>
            </div>

          </div>

        </div>
      </div>

      {/* 2. 중간 겹쳐지는 토스 제휴 이벤트 카드 배너 */}
      <div className="w-full max-w-5xl px-6 mt-12 mb-[-50px] z-30 grid grid-cols-1 md:grid-cols-2 gap-6">
        <div className="bg-gradient-to-r from-[#111827] to-[#1f2937] text-white rounded-2xl p-6 shadow-2xl flex items-center justify-between border border-zinc-700">
          <div>
            <div className="flex items-center gap-2 mb-2">
              <span className="text-[10px] font-extrabold text-sky-400 bg-sky-950/60 px-2 py-0.5 rounded">toss payments</span>
              <span className="text-[10px] text-zinc-400">×</span>
              <span className="text-[10px] font-extrabold text-white">MEGABOX</span>
            </div>
            <h4 className="text-lg font-black leading-snug tracking-tight">
              퀵계좌이체 결제 시<br />
              <strong className="text-sky-400">0.3% 무제한 즉시할인</strong>
            </h4>
          </div>
          <div className="text-3xl">🍿</div>
        </div>

        <div className="bg-gradient-to-r from-[#18202c] to-[#111827] text-white rounded-2xl p-6 shadow-2xl flex items-center justify-between border border-zinc-700">
          <div>
            <span className="text-[10px] font-bold text-zinc-400 block mb-1">토스 퀵계좌이체</span>
            <h4 className="text-lg font-black text-white tracking-tight">
              0.3% 즉시할인
            </h4>
          </div>
          <div className="w-12 h-12 rounded-full bg-blue-600/20 border border-blue-400/40 flex items-center justify-center text-blue-400 font-black text-lg shadow-inner">
            %
          </div>
        </div>
      </div>

      {/* 3. 하단 보라색 퀵 메뉴 바 */}
      <div className="w-full bg-[#503396] pt-20 pb-12 px-6 text-white flex justify-center shadow-inner">
        <div className="w-full max-w-4xl flex items-center justify-around text-center">
          
          <div className="flex flex-col items-center gap-2 cursor-pointer hover:opacity-80 transition">
            <svg className="w-6 h-6 stroke-current" fill="none" viewBox="0 0 24 24" strokeWidth="1.8">
              <path strokeLinecap="round" strokeLinejoin="round" d="M12 2l9 4.909v9.182L12 21l-9-4.909V6.909L12 2z" />
            </svg>
            <span className="text-xs font-bold tracking-wide">VIP LOUNGE</span>
          </div>

          <div className="flex flex-col items-center gap-2 cursor-pointer hover:opacity-80 transition">
            <svg className="w-6 h-6 stroke-current" fill="none" viewBox="0 0 24 24" strokeWidth="1.8">
              <circle cx="12" cy="7" r="4" />
              <path strokeLinecap="round" strokeLinejoin="round" d="M4 21v-2a4 4 0 0 1 4-4h8a4 4 0 0 1 4 4v2" />
            </svg>
            <span className="text-xs font-bold tracking-wide">멤버십</span>
          </div>

          <div className="flex flex-col items-center gap-2 cursor-pointer hover:opacity-80 transition">
            <svg className="w-6 h-6 stroke-current" fill="none" viewBox="0 0 24 24" strokeWidth="1.8">
              <rect x="2" y="5" width="20" height="14" rx="2" />
              <path strokeLinecap="round" strokeLinejoin="round" d="M2 10h20" />
            </svg>
            <span className="text-xs font-bold tracking-wide">할인카드안내</span>
          </div>

          <div className="flex flex-col items-center gap-2 cursor-pointer hover:opacity-80 transition">
            <svg className="w-6 h-6 stroke-current" fill="none" viewBox="0 0 24 24" strokeWidth="1.8">
              <path strokeLinecap="round" strokeLinejoin="round" d="M20 12v10H4V12M2 7h20v5H2zM12 22V7M12 7H7.5a2.5 2.5 0 0 1 0-5C11 2 12 7 12 7zM12 7h4.5a2.5 2.5 0 0 0 0-5C13 2 12 7 12 7z" />
            </svg>
            <span className="text-xs font-bold tracking-wide">이벤트</span>
          </div>

          <div className="flex flex-col items-center gap-2 cursor-pointer hover:opacity-80 transition">
            <svg className="w-6 h-6 stroke-current" fill="none" viewBox="0 0 24 24" strokeWidth="1.8">
              <path strokeLinecap="round" strokeLinejoin="round" d="M7 21h10a2 2 0 0 0 2-2V9.414a1 1 0 0 0-.293-.707l-5.414-5.414A1 1 0 0 0 12.586 3H7a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2z" />
            </svg>
            <span className="text-xs font-bold tracking-wide">스토어</span>
          </div>

        </div>
      </div>

    </section>
  );
}

export default DestinationGrid;
